import React, { useEffect, useState } from 'react';
import { api } from '../../services/api';
import type { ArtistCredit } from '../../types';

const minReleaseDate = () => { const d=new Date(); d.setDate(d.getDate()+7); const y=d.getFullYear(); const m=String(d.getMonth()+1).padStart(2,'0'); const day=String(d.getDate()).padStart(2,'0'); return `${y}-${m}-${day}`; };
const OFFICIAL_LANGUAGES = ['Afrikaans','English','isiNdebele','isiXhosa','isiZulu','Sepedi','Sesotho','Setswana','siSwati','Tshivenda','Xitsonga','South African Sign Language'];
const GENRES = ['Afrobeats','Afro-pop','Alternative','Blues','Classical','Country','Dance','Electronic','Gospel','Hip-Hop/Rap','Jazz','Pop','R&B/Soul','Reggae','Rock','Traditional','World'];
const SUB_GENRES = ['Amapiano','3-Step','Afro House','Afro Tech','Deep House','Deep Tech','Gqom','Bacardi','Private School Amapiano','Soulful House','Tech House','Other'];
const STORES = ['Spotify','Apple Music','Amazon Music','YouTube Music','Deezer','TIDAL','Boomplay','Audiomack','TikTok Music','Shazam','YouTube Content ID'];
