type ContributorRow = { name: string; role: string };
type TrackMetadata = {
  title:string; primaryArtists:string; featuredArtists:string; genre:string; subGenre:string; version:string;
  language:string; lyricsLanguage:string; countryOfRecording:string; composers:string; producers:string; publishers:string;
  lyrics:string; explicit:boolean; previouslyReleased:boolean; originalReleaseDate:string; previousISRC:string; previousUPC:string;
  previewStart:string; digitalReleaseDate:string; instrumental:boolean; coverSong:boolean; label:string; cLine:string; pLine:string; parentalAdvisory:string;
  clean:boolean; requestContentId:boolean; publishing:boolean; additionalInfo:string;
  writers:ContributorRow[]; publisherRows:ContributorRow[]; producerRows:ContributorRow[];
  additionalPerformers:ContributorRow[]; additionalContributors:ContributorRow[];
};
const blankContributors = ():ContributorRow[] => [{name:'',role:''}];
const emptyTrackMetadata = (file?:File, defaults:Partial<TrackMetadata> = {}):TrackMetadata => ({
  title:file?.name.replace(/\.mp3$/i,'')||'',primaryArtists:'',featuredArtists:'',genre:'',subGenre:'',version:'1.0',language:'',lyricsLanguage:'',countryOfRecording:'',composers:'',producers:'',publishers:'',lyrics:'',explicit:false,previouslyReleased:false,originalReleaseDate:'',previousISRC:'',previousUPC:'',previewStart:'0',digitalReleaseDate:'',instrumental:false,coverSong:false,label:'',cLine:'',pLine:'',parentalAdvisory:'No',clean:false,requestContentId:false,publishing:false,additionalInfo:'',writers:blankContributors(),publisherRows:blankContributors(),producerRows:blankContributors(),additionalPerformers:blankContributors(),additionalContributors:blankContributors(),...defaults
});
type ArtistRow = { name: string; spotifyProfileUrl: string; appleMusicProfileUrl: string; createNew: boolean; social1: string; social2: string; social3: string };
const emptyArtist = (): ArtistRow => ({ name: '', spotifyProfileUrl: '', appleMusicProfileUrl: '', createNew: false, social1: '', social2: '', social3: '' });

export const AudioSubmissions: React.FC<{ onSubmitted?: () => void }> = ({ onSubmitted }) => {
  const [releaseType,setReleaseType]=useState<'Single'|'EP'|'Album'>('Single');
  const [page,setPage]=useState<'entry'|'choose'|'form'>('entry');
  const [trackMetadata,setTrackMetadata]=useState<TrackMetadata[]>([]);
  const [trackFiles,setTrackFiles]=useState<Array<File|null>>([]);
  const addEmptyTrack=()=>{setTrackMetadata(rows=>[...rows,emptyTrackMetadata()]);setTrackFiles(rows=>[...rows,null]);};
  const setTrackFile=(index:number,file:File|null)=>{setTrackFiles(rows=>rows.map((row,i)=>i===index?file:row));if(file)setTrackMetadata(rows=>rows.map((row,i)=>i===index?({...row,title:row.title||file.name.replace(/\.mp3$/i,'')}):row));};
  const validateAndSetTrackFile=async(index:number,file:File|null)=>{if(!file){setTrackFile(index,null);return;}if(!/\.mp3$/i.test(file.name)){setError(`Track ${index+1} must be an MP3 file.`);return;}try{const AudioContextClass=window.AudioContext|| (window as any).webkitAudioContext;if(!AudioContextClass){setTrackFile(index,file);return;}const context=new AudioContextClass();const decoded=await context.decodeAudioData(await file.arrayBuffer());await context.close();if(decoded.duration<60){setError(`Track ${index+1} must be at least 60 seconds long.`);return;}if(decoded.numberOfChannels<2){setError(`Track ${index+1} must be a stereo audio file.`);return;}setError('');setTrackFile(index,file);}catch{setError(`Could not validate Track ${index+1}. Please upload a valid MP3 audio file.`);}};
  const updateTrackMetadata=<K extends keyof TrackMetadata>(index:number,field:K,value:TrackMetadata[K])=>setTrackMetadata(rows=>rows.map((row,i)=>i===index?({...row,[field]:value}):row));
  const removeTrack=(index:number)=>{setTrackFiles(rows=>rows.filter((_,i)=>i!==index));setTrackMetadata(rows=>rows.filter((_,i)=>i!==index));};
  const [title,setTitle]=useState(''); const [artistRows,setArtistRows]=useState<ArtistRow[]>([emptyArtist()]); const [featuredRows,setFeaturedRows]=useState<ArtistRow[]>([]);
  const [genre,setGenre]=useState(''); const [subGenre,setSubGenre]=useState(''); const [labelName,setLabelName]=useState('');
  const [version,setVersion]=useState('1.0'); const [language,setLanguage]=useState(''); const [lyricsLanguage,setLyricsLanguage]=useState('');
  const [releaseDate,setReleaseDate]=useState('');
  const [composerCredits,setComposerCredits]=useState<Array<{firstName:string;surname:string}>>([{firstName:'',surname:''}]);
  const [producerCredits,setProducerCredits]=useState<Array<{firstName:string;surname:string}>>([{firstName:'',surname:''}]);
  const [publisherCredits,setPublisherCredits]=useState<Array<{firstName:string;surname:string}>>([{firstName:'',surname:''}]);
  const updateCreditRow=(kind:'composer'|'producer'|'publisher',index:number,field:'firstName'|'surname',value:string)=>{
    const setter=kind==='composer'?setComposerCredits:kind==='producer'?setProducerCredits:setPublisherCredits;
    setter(rows=>rows.map((row,i)=>i===index?{...row,[field]:value}:row));
  };
  const [lyrics,setLyrics]=useState(''); const [previewMinutes,setPreviewMinutes]=useState('0'); const [previewSeconds,setPreviewSeconds]=useState('00'); const [previouslyReleased,setPreviouslyReleased]=useState(false); const [originalReleaseDate,setOriginalReleaseDate]=useState(''); const [previousIsrc,setPreviousIsrc]=useState(''); const [previousUpc,setPreviousUpc]=useState(''); const [explicit,setExplicit]=useState(false);
  const [files,setFiles]=useState<File[]>([]); const [trackTitles,setTrackTitles]=useState(''); const [artwork,setArtwork]=useState<File|null>(null);
  const [dspSelections,setDspSelections]=useState<string[]>(['Spotify','Apple Music','YouTube Music']);
  const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [notice,setNotice]=useState(''); const [knownArtists,setKnownArtists]=useState<ArtistCredit[]>([]);
  const loadArtistLibrary=async()=>{try{const r=await api.getArtistLibrary();setKnownArtists((r.artists||[]).filter(a=>a.name));}catch{}};
  const updateArtistName = (role:'primary'|'featured', index:number, name:string) => {
    const saved = knownArtists.find(a => a.name.trim().toLocaleLowerCase() === name.trim().toLocaleLowerCase());
    const update = (rows:ArtistRow[]) => rows.map((row,i) => i===index ? {
      ...row,
      name,
      ...(saved ? {
        spotifyProfileUrl: saved.spotifyProfileUrl || '',
        appleMusicProfileUrl: saved.appleMusicProfileUrl || '',
        createNew: !!(saved.spotifyProfileCreateRequested || saved.appleMusicProfileCreateRequested),
        social1: saved.socialMediaLinks?.[0] || '',
        social2: saved.socialMediaLinks?.[1] || '',
        social3: saved.socialMediaLinks?.[2] || '',
      } : {
        spotifyProfileUrl: '', appleMusicProfileUrl: '', createNew: false,
        social1: '', social2: '', social3: '',
      }),
    } : row);
    if(role==='primary') setArtistRows(update); else setFeaturedRows(update);
  };
  useEffect(()=>{void loadArtistLibrary();},[]);
  const addArtistRow=async(role:'primary'|'featured')=>{const rows=role==='primary'?artistRows:featuredRows;try{for(const artist of rows.filter(a=>a.name.trim())){await api.saveArtist({name:artist.name.trim(),role,spotifyProfileUrl:artist.spotifyProfileUrl||undefined,appleMusicProfileUrl:artist.appleMusicProfileUrl||undefined,spotifyProfileCreateRequested:artist.createNew,appleMusicProfileCreateRequested:artist.createNew,socialMediaLinks:[artist.social1,artist.social2,artist.social3].filter(Boolean)});}if(rows.some(a=>a.name.trim()))await loadArtistLibrary();}catch(e:any){setError(e.message||'Could not save the artist to your library.');return;}if(role==='primary')setArtistRows(v=>[...v,emptyArtist()]);else setFeaturedRows(v=>[...v,emptyArtist()]);};
  const toggleStore=(name:string)=>setDspSelections(v=>v.includes(name)?v.filter(x=>x!==name):[...v,name]);
  const startRelease=(type:'Single'|'EP'|'Album')=>{if(type!==releaseType){setFiles([]);setTrackMetadata([]);setTrackFiles([]);setArtwork(null);setTitle('');setTrackTitles('');}setReleaseType(type);setPage('form');};
  const submit=async(e:React.FormEvent)=>{
    e.preventDefault(); setError('');setNotice('');
    if(!artwork) return setError('Upload your square JPG/PNG cover artwork.');
    if(!title.trim()||(releaseType==='Single'&&!artistRows.some(a=>a.name.trim()))||(releaseType==='Single'&&!genre.trim())) return setError('Complete the release title, at least one primary artist and genre.');
    if(previouslyReleased&&(!originalReleaseDate||!previousIsrc.trim()||!previousUpc.trim())) return setError('For a previously released song, provide the original release date, ISRC and UPC.');
    if(releaseType==='Single'&&files.length>1) return setError('A Single can contain only one optional MP3 preview. Choose EP or Album for multiple tracks.');
    for (const artist of [...artistRows.filter(a=>a.name.trim()), ...featuredRows.filter(a=>a.name.trim())]) { if (!artist.createNew && (!artist.spotifyProfileUrl.trim() || !artist.appleMusicProfileUrl.trim())) return setError(`Add Spotify and Apple Music profile links for ${artist.name}, or choose Create new profiles.`); if (artist.createNew && ![artist.social1,artist.social2,artist.social3].some(x=>x.trim())) return setError(`Add at least one social-media link for ${artist.name} to request new artist profiles.`); }
    const creditGroups = [
      ['Composer', composerCredits], ['Producer', producerCredits], ['Publisher', publisherCredits],
    ] as const;
    for (const [label, rows] of creditGroups) {
      if (rows.some(row => (row.firstName.trim() && !row.surname.trim()) || (!row.firstName.trim() && row.surname.trim()))) {
        return setError(`${label} credits require both a real first name and surname in their separate fields.`);
      }
    }
    const audioFiles: Array<File|null> = releaseType==='Single' ? files : trackFiles;
    if(audioFiles.length===0) return setError('Add at least one song and upload its MP3 master.');
    if(releaseType!=='Single'&&audioFiles.length<2) return setError('An EP or Album must contain at least two songs.');
    if(releaseType!=='Single') { for(let i=0;i<audioFiles.length;i++){const t=trackMetadata[i];if(!audioFiles[i])return setError(`Upload the MP3 audio file for Track ${i+1}.`);if(!t||!t.title.trim()||!t.genre||!t.language||!t.countryOfRecording||!t.digitalReleaseDate||!t.primaryArtists.trim())return setError(`Complete the title, primary artist, genre, song language and country of recording for Track ${i+1}.`);if(t.previouslyReleased&&(!t.originalReleaseDate||!t.previousISRC.trim()||!t.previousUPC.trim()))return setError(`Track ${i+1} was previously released. Add its original release date, ISRC and UPC.`);const namedWriters=t.writers.filter(c=>c.name.trim()&&c.role);if(!namedWriters.some(c=>c.role==='Composer (C)')||!namedWriters.some(c=>c.role==='Author (A)'))return setError(`Track ${i+1} needs at least one Writer with role Composer (C) and one with role Author (A).`);if(!t.producerRows.some(c=>c.name.trim()&&c.role))return setError(`Track ${i+1} needs at least one Producer.`);} }
    const names=trackTitles.split('\n').map(v=>v.trim()).filter(Boolean);
    if(releaseType==='Single'&&names.length&&names.length!==files.length) return setError('Enter one track title per audio file, or leave the track title box empty to use file names.');
    try{
      setBusy(true);
      const art=await api.uploadArtwork(artwork);
      const uploaded=[];
      for(let i=0;i<audioFiles.length;i++){
        const sourceFile=audioFiles[i]!; const audio=await api.uploadAudio(sourceFile);
        const meta=releaseType==='Single'?undefined:trackMetadata[i];
        const split=(value:string)=>value.split(',').map(x=>x.trim()).filter(Boolean);
        uploaded.push({id:`track-${Date.now()}-${i}`,title:meta?.title||names[i]||sourceFile.name.replace(/\.mp3$/i,''),filename:audio.filename,storedFilename:audio.storedFilename,fileUrl:audio.fileUrl,fileSize:audio.fileSize,version:meta?.version||version,...(meta?{primaryArtists:split(meta.primaryArtists),featuredArtists:split(meta.featuredArtists),genre:meta.genre,subGenre:meta.subGenre,language:meta.language,lyricsLanguage:meta.lyricsLanguage,countryOfRecording:meta.countryOfRecording,composers:split(meta.composers),producers:split(meta.producers),publishers:split(meta.publishers),lyrics:meta.lyrics,previouslyReleased:meta.previouslyReleased,originalReleaseDate:meta.originalReleaseDate,previousISRC:meta.previousISRC,previousUPC:meta.previousUPC,previewStart:Number(meta.previewStart)||0,digitalReleaseDate:meta.digitalReleaseDate,explicit:meta.parentalAdvisory==='Yes',instrumental:meta.instrumental,coverSong:meta.coverSong,label:meta.label,cLine:meta.cLine,pLine:meta.pLine,parentalAdvisory:meta.parentalAdvisory,clean:meta.clean,requestContentId:meta.requestContentId,publishing:meta.publishing,additionalInfo:meta.additionalInfo,writers:meta.writers,trackPublishers:meta.publisherRows,trackProducers:meta.producerRows,additionalPerformers:meta.additionalPerformers,additionalContributors:meta.additionalContributors}:{})});
      }
      const trackArtistNames=(value:string)=>value.split(',').map(x=>x.trim()).filter(Boolean);
      const releasePrimaryArtists=releaseType==='Single'?artistRows.map(a=>a.name.trim()).filter(Boolean):Array.from(new Set(trackMetadata.flatMap(t=>trackArtistNames(t.primaryArtists))));
      const releaseFeaturedArtists=releaseType==='Single'?featuredRows.map(a=>a.name.trim()).filter(Boolean):Array.from(new Set(trackMetadata.flatMap(t=>trackArtistNames(t.featuredArtists))));
      const result=await api.createRelease({
        title,releaseType,primaryArtists:releasePrimaryArtists,featuredArtists:releaseFeaturedArtists,primaryArtistProfiles:artistRows.filter(a=>a.name.trim()).map(a=>({name:a.name.trim(),role:'primary',spotifyProfileUrl:a.spotifyProfileUrl,appleMusicProfileUrl:a.appleMusicProfileUrl,spotifyProfileCreateRequested:a.createNew,appleMusicProfileCreateRequested:a.createNew,socialMediaLinks:[a.social1,a.social2,a.social3].filter(Boolean)})),featuredArtistProfiles:featuredRows.filter(a=>a.name.trim()).map(a=>({name:a.name.trim(),role:'featured',spotifyProfileUrl:a.spotifyProfileUrl,appleMusicProfileUrl:a.appleMusicProfileUrl,spotifyProfileCreateRequested:a.createNew,appleMusicProfileCreateRequested:a.createNew,socialMediaLinks:[a.social1,a.social2,a.social3].filter(Boolean)})),labelName,
        genre:releaseType==='Single'?genre:(trackMetadata.find(t=>t.genre)?.genre||''),subGenre:releaseType==='Single'?subGenre:(trackMetadata[0]?.subGenre||''),language:releaseType==='Single'?language:(trackMetadata[0]?.language||''),lyricsLanguage:releaseType==='Single'?lyricsLanguage:(trackMetadata[0]?.lyricsLanguage||''),version,lyrics:releaseType==='Single'?lyrics:'',previewStart:releaseType==='Single'?((Number(previewMinutes)*60)+Number(previewSeconds)):undefined,
        composers:composerCredits.filter(row=>row.firstName.trim()&&row.surname.trim()).map(row=>`${row.firstName.trim()} ${row.surname.trim()}`),
        producers:producerCredits.filter(row=>row.firstName.trim()&&row.surname.trim()).map(row=>`${row.firstName.trim()} ${row.surname.trim()}`),
        publishers:publisherCredits.filter(row=>row.firstName.trim()&&row.surname.trim()).map(row=>`${row.firstName.trim()} ${row.surname.trim()}`),targetReleaseDate:releaseDate,previouslyReleased,originalReleaseDate:previouslyReleased?originalReleaseDate:undefined,previousISRC:previouslyReleased?previousIsrc:undefined,previousUPC:previouslyReleased?previousUpc:undefined,
        artworkUrl:art.fileUrl,artworkFilename:art.filename,storedArtworkFilename:art.storedFilename,artworkDimensions:art.dimensions,
        tracks:uploaded.map((t:any,i:number)=>({...t,trackNumber:i+1,explicit:releaseType==='Single'?explicit:!!t.explicit})),audioMasterPending:false,dspSelections,clientNotes:`Label: ${labelName||'STB Academy'}; Explicit: ${explicit?'Yes':'No'}. MP3 master supplied through the portal.`
      });
      await loadArtistLibrary();
      setNotice(`Submitted successfully. Reference: ${result.release.refNumber}. Your MP3 master files were uploaded with this submission.`);
      setTitle('');setArtistRows([emptyArtist()]);setFeaturedRows([]);setGenre('');setSubGenre('');setLabelName('');setVersion('1.0');setLanguage('');setLyricsLanguage('');setReleaseDate('');setComposerCredits([{firstName:'',surname:''}]);setProducerCredits([{firstName:'',surname:''}]);setPublisherCredits([{firstName:'',surname:''}]);setLyrics('');setPreviewMinutes('0');setPreviewSeconds('00');setPreviouslyReleased(false);setOriginalReleaseDate('');setPreviousIsrc('');setPreviousUpc('');setExplicit(false);setFiles([]);setTrackTitles('');setTrackMetadata([]);setTrackFiles([]);setArtwork(null);setPage('entry');onSubmitted?.();
    }catch(err:any){setError(err?.message||'Could not submit this release.');}
    finally{setBusy(false);}
  };
  if(page!=='form') return <section id="stb-audio-submissions" className={`${page==='choose'?'fixed inset-0 z-[90] min-h-screen overflow-y-auto bg-neutral-950 p-4 sm:p-8':'mb-8'} rounded-2xl border border-orange-900/40 bg-neutral-900/70 p-5 sm:p-6`}>
    <div className={page==='choose'?'mx-auto max-w-5xl':''}>
    <p className="text-[10px] font-black uppercase tracking-[.22em] text-orange-400">Audio distribution</p>
    {page==='entry'?<><h2 className="mt-1 text-lg font-bold text-white">Audio releases</h2><p className="mt-1 text-xs text-neutral-400">Start a new music distribution submission.</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><button type="button" onClick={()=>setPage('choose')} className="rounded-xl border border-orange-700/60 bg-orange-950/20 p-5 text-left hover:bg-orange-950/40"><span className="block text-sm font-bold text-white">Create Audio Release</span><span className="mt-1 block text-xs text-neutral-400">Start a new EP or Album with multiple songs.</span></button><button type="button" onClick={()=>startRelease('Single')} className="rounded-xl border border-neutral-700 bg-neutral-950/60 p-5 text-left hover:border-orange-700"><span className="block text-sm font-bold text-white">Create Single Release</span><span className="mt-1 block text-xs text-neutral-400">Submit one song using the existing Single submission form.</span></button></div></>:<><div className="mt-3 flex items-center justify-between gap-3"><div><h2 className="text-lg font-bold text-white">Choose audio release type</h2><p className="mt-1 text-xs text-neutral-400">Select the format you want to submit.</p></div><button type="button" onClick={()=>setPage('entry')} className="rounded-lg border border-neutral-700 px-3 py-2 text-xs text-neutral-300">Back</button></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><button type="button" onClick={()=>startRelease('EP')} className="rounded-xl border border-orange-700/60 bg-orange-950/20 p-5 text-left hover:bg-orange-950/40"><span className="block text-sm font-bold text-white">Create an EP</span><span className="mt-1 block text-xs text-neutral-400">Submit multiple tracks, each with its own metadata.</span></button><button type="button" onClick={()=>startRelease('Album')} className="rounded-xl border border-orange-700/60 bg-orange-950/20 p-5 text-left hover:bg-orange-950/40"><span className="block text-sm font-bold text-white">Create an Album</span><span className="mt-1 block text-xs text-neutral-400">Submit a full album with individual track information.</span></button></div></>}</div></section>;
  return <section id="stb-audio-submissions" className="fixed inset-0 z-[90] min-h-screen overflow-y-auto bg-neutral-950 p-4 sm:p-8"><div className="mx-auto max-w-5xl rounded-2xl border border-orange-900/40 bg-neutral-900/70 p-5 sm:p-6">
    <div className="mb-5 flex items-start justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-[.22em] text-orange-400">Audio distribution · {releaseType}</p><h2 className="mt-1 text-lg font-bold text-white">Create {releaseType} release</h2><p className="mt-1 text-xs text-neutral-400">{releaseType==='Single'?'Submit one song for review and distribution.':'Add each song separately, including its own metadata and country of recording.'}</p></div><button type="button" onClick={()=>setPage(releaseType==='Single'?'entry':'choose')} className="shrink-0 rounded-lg border border-neutral-700 px-3 py-2 text-xs text-neutral-300">← Back</button></div>
    <form onSubmit={submit} className="grid gap-3 sm:grid-cols-2">
      <datalist id="stbacademy-audio-known-artists">{knownArtists.map(artist=><option key={artist.id || artist.name} value={artist.name}/>)}</datalist>
      <p className="sm:col-span-2 text-[10px] text-neutral-500">Saved artists include their Spotify, Apple Music and social links. Select a saved artist to automatically restore those links; clicking an Add Artist button saves the entered artist and links to your account.</p>
      <label className="text-xs text-neutral-300">Release type<input readOnly value={releaseType} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-900 px-3 py-2.5 text-sm text-neutral-300"/></label>
      <label className="text-xs text-neutral-300">Release title *<input required value={title} onChange={e=>setTitle(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white" placeholder="Official release title"/></label>
      <div className="sm:col-span-2 space-y-3"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-neutral-200">Primary artists {releaseType==='Single'?'*':'(track artists are entered separately below)'}</span><button type="button" onClick={()=>void addArtistRow('primary')} className="rounded-lg bg-neutral-800 px-3 py-2 text-[11px] text-white">+ Add primary artist</button></div>{artistRows.map((artist,index)=><div key={index} className="rounded-xl border border-neutral-800 bg-neutral-950/70 p-3 space-y-2"><div className="flex gap-2"><input list="stbacademy-audio-known-artists" value={artist.name} onChange={e=>updateArtistName('primary',index,e.target.value)} placeholder="Select a saved artist or enter a new stage name" className="min-w-0 flex-1 rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/>{artistRows.length>1&&<button type="button" onClick={()=>setArtistRows(v=>v.filter((_,i)=>i!==index))} className="px-2 text-xs text-red-300">Remove</button>}</div><label className="flex items-center gap-2 text-[11px] text-neutral-300"><input type="checkbox" checked={artist.createNew} onChange={e=>setArtistRows(v=>v.map((x,i)=>i===index?{...x,createNew:e.target.checked}:x))}/> Create new Spotify and Apple Music profiles</label>{!artist.createNew?<div className="grid sm:grid-cols-2 gap-2"><input value={artist.spotifyProfileUrl} onChange={e=>setArtistRows(v=>v.map((x,i)=>i===index?{...x,spotifyProfileUrl:e.target.value}:x))} placeholder="Spotify artist profile URL" className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/><input value={artist.appleMusicProfileUrl} onChange={e=>setArtistRows(v=>v.map((x,i)=>i===index?{...x,appleMusicProfileUrl:e.target.value}:x))} placeholder="Apple Music artist profile URL" className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/></div>:<div className="grid sm:grid-cols-3 gap-2">{(['social1','social2','social3'] as const).map((key,i)=><input key={key} value={artist[key]} onChange={e=>setArtistRows(v=>v.map((x,j)=>j===index?{...x,[key]:e.target.value}:x))} placeholder={`Social link ${i+1}${i===0?' (required)':' (optional)'}`} className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/>)}<p className="sm:col-span-3 text-[10px] text-neutral-500">At least one social link is required. Three links help us identify the correct artist, but the second and third are optional.</p></div>}</div>)}</div>
      <div className="sm:col-span-2 space-y-3"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-neutral-200">Featured artists (optional)</span><button type="button" onClick={()=>void addArtistRow('featured')} className="rounded-lg bg-neutral-800 px-3 py-2 text-[11px] text-white">+ Add featured artist</button></div>{featuredRows.map((artist,index)=><div key={index} className="rounded-xl border border-neutral-800 bg-neutral-950/70 p-3 space-y-2"><div className="flex gap-2"><input list="stbacademy-audio-known-artists" value={artist.name} onChange={e=>updateArtistName('featured',index,e.target.value)} placeholder="Select a saved artist or enter a new stage name" className="min-w-0 flex-1 rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/><button type="button" onClick={()=>setFeaturedRows(v=>v.filter((_,i)=>i!==index))} className="px-2 text-xs text-red-300">Remove</button></div><label className="flex items-center gap-2 text-[11px] text-neutral-300"><input type="checkbox" checked={artist.createNew} onChange={e=>setFeaturedRows(v=>v.map((x,i)=>i===index?{...x,createNew:e.target.checked}:x))}/> Create new Spotify and Apple Music profiles</label>{!artist.createNew?<div className="grid sm:grid-cols-2 gap-2"><input value={artist.spotifyProfileUrl} onChange={e=>setFeaturedRows(v=>v.map((x,i)=>i===index?{...x,spotifyProfileUrl:e.target.value}:x))} placeholder="Spotify artist profile URL" className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/><input value={artist.appleMusicProfileUrl} onChange={e=>setFeaturedRows(v=>v.map((x,i)=>i===index?{...x,appleMusicProfileUrl:e.target.value}:x))} placeholder="Apple Music artist profile URL" className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/></div>:<div className="grid sm:grid-cols-3 gap-2">{(['social1','social2','social3'] as const).map((key,i)=><input key={key} value={artist[key]} onChange={e=>setFeaturedRows(v=>v.map((x,j)=>j===index?{...x,[key]:e.target.value}:x))} placeholder={`Social link ${i+1}${i===0?' (required)':' (optional)'}`} className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/>)}<p className="sm:col-span-3 text-[10px] text-neutral-500">At least one social link is required for new profile requests.</p></div>}</div>)}</div>
      {releaseType==='Single'&&<label className="text-xs text-neutral-300">Genre *<select required value={genre} onChange={e=>setGenre(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"><option value="">Select genre</option>{GENRES.map(x=><option key={x}>{x}</option>)}</select></label>}
      {releaseType==='Single'&&<label className="text-xs text-neutral-300">Sub-genre<select value={subGenre} onChange={e=>setSubGenre(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"><option value="">Select sub-genre (optional)</option>{SUB_GENRES.map(x=><option key={x}>{x}</option>)}</select></label>}
      <label className="text-xs text-neutral-300">Label (optional)<input value={labelName} onChange={e=>setLabelName(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white" placeholder="Your label name"/></label>
      {releaseType==='Single'&&<label className="text-xs text-neutral-300">Version<input value={version} onChange={e=>setVersion(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white" placeholder="1.0"/></label>}
      {releaseType==='Single'&&<label className="text-xs text-neutral-300">Song language *<select required value={language} onChange={e=>setLanguage(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"><option value="">Select official language</option>{OFFICIAL_LANGUAGES.map(x=><option key={x}>{x}</option>)}</select></label>}
      {releaseType==='Single'&&<label className="text-xs text-neutral-300">Lyrics language<select value={lyricsLanguage} onChange={e=>setLyricsLanguage(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"><option value="">Same as song / not specified</option>{OFFICIAL_LANGUAGES.map(x=><option key={x}>{x}</option>)}</select></label>}
      <label className="text-xs text-neutral-300">Target release date * (minimum 7 days ahead)<input required type="date" value={releaseDate} onChange={e=>setReleaseDate(e.target.value)} min={minReleaseDate()} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/></label>
      {releaseType==='Single'&&<div className="text-xs text-neutral-300">Preview start time (optional)<div className="mt-1 flex gap-2"><label className="flex-1">Minutes<select value={previewMinutes} onChange={e=>setPreviewMinutes(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white">{Array.from({length:60},(_,i)=><option key={i} value={i}>{String(i).padStart(2,'0')}</option>)}</select></label><label className="flex-1">Seconds<select value={previewSeconds} onChange={e=>setPreviewSeconds(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white">{Array.from({length:60},(_,i)=><option key={i} value={String(i).padStart(2,'0')}>{String(i).padStart(2,'0')}</option>)}</select></label></div></div>}
{releaseType==='Single'&&<><div className="text-xs text-neutral-300"><div className="flex items-center justify-between"><span className="font-semibold">Composer(s) — real first name and surname</span><button type="button" onClick={()=>setComposerCredits(rows=>[...rows,{firstName:'',surname:''}])} className="text-[10px] text-orange-300">+ Add contributor</button></div>{composerCredits.map((row,index)=><div key={index} className="mt-1 grid grid-cols-[1fr_1fr_auto] gap-2"><input value={row.firstName} onChange={e=>updateCreditRow('composer',index,'firstName',e.target.value)} placeholder="First name" className="min-w-0 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/><input value={row.surname} onChange={e=>updateCreditRow('composer',index,'surname',e.target.value)} placeholder="Surname" className="min-w-0 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/>{composerCredits.length>1&&<button type="button" onClick={()=>setComposerCredits(rows=>rows.filter((_,i)=>i!==index))} className="px-1 text-red-300">×</button>}</div>)}</div>
      <div className="text-xs text-neutral-300"><div className="flex items-center justify-between"><span className="font-semibold">Producer(s) — real first name and surname</span><button type="button" onClick={()=>setProducerCredits(rows=>[...rows,{firstName:'',surname:''}])} className="text-[10px] text-orange-300">+ Add contributor</button></div>{producerCredits.map((row,index)=><div key={index} className="mt-1 grid grid-cols-[1fr_1fr_auto] gap-2"><input value={row.firstName} onChange={e=>updateCreditRow('producer',index,'firstName',e.target.value)} placeholder="First name" className="min-w-0 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/><input value={row.surname} onChange={e=>updateCreditRow('producer',index,'surname',e.target.value)} placeholder="Surname" className="min-w-0 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/>{producerCredits.length>1&&<button type="button" onClick={()=>setProducerCredits(rows=>rows.filter((_,i)=>i!==index))} className="px-1 text-red-300">×</button>}</div>)}</div>
      <div className="text-xs text-neutral-300"><div className="flex items-center justify-between"><span className="font-semibold">Publisher(s) — real name (optional)</span><button type="button" onClick={()=>setPublisherCredits(rows=>[...rows,{firstName:'',surname:''}])} className="text-[10px] text-orange-300">+ Add contributor</button></div>{publisherCredits.map((row,index)=><div key={index} className="mt-1 grid grid-cols-[1fr_1fr_auto] gap-2"><input value={row.firstName} onChange={e=>updateCreditRow('publisher',index,'firstName',e.target.value)} placeholder="First name" className="min-w-0 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/><input value={row.surname} onChange={e=>updateCreditRow('publisher',index,'surname',e.target.value)} placeholder="Surname" className="min-w-0 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/>{publisherCredits.length>1&&<button type="button" onClick={()=>setPublisherCredits(rows=>rows.filter((_,i)=>i!==index))} className="px-1 text-red-300">×</button>}</div>)}</div></>}
      <label className="text-xs text-neutral-300 sm:col-span-2">Cover artwork * (JPG/PNG, RGB, square, 1500×1500 minimum, 3000×3000 recommended)<input required type="file" accept="image/jpeg,image/png,.jpg,.jpeg,.png" onChange={e=>setArtwork(e.target.files?.[0]||null)} className="mt-1 block w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-xs text-white file:mr-3 file:rounded-lg file:border-0 file:bg-neutral-800 file:px-3 file:py-2 file:text-white"/></label>
      {releaseType==='Single'&&<label className="text-xs text-neutral-300 sm:col-span-2">MP3 master upload * (required)<input required type="file" multiple accept=".mp3,audio/mpeg" onChange={e=>setFiles(Array.from(e.target.files||[]))} className="mt-1 block w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-xs text-white file:mr-3 file:rounded-lg file:border-0 file:bg-neutral-800 file:px-3 file:py-2 file:text-white"/></label>}
      {releaseType!=='Single'&&<div className="sm:col-span-2 space-y-4"><div className="flex items-center justify-between gap-3"><div><h3 className="text-sm font-bold text-white">Track submissions</h3><p className="mt-1 text-[11px] text-neutral-400">Every song has its own complete metadata and separate MP3 upload.</p></div><button type="button" onClick={addEmptyTrack} className="rounded-xl bg-orange-600 px-4 py-2.5 text-xs font-bold text-white">+ Add Song</button></div>
      {trackMetadata.map((meta,index)=><article key={index} className="rounded-xl border border-orange-900/40 bg-neutral-950/70 p-4 space-y-4"><div className="flex items-center justify-between"><div><p className="text-[10px] font-black uppercase tracking-wider text-orange-400">Track {index+1}</p><p className="text-xs text-neutral-400">{trackFiles[index]?.name||'No audio file selected yet'}</p></div><button type="button" onClick={()=>removeTrack(index)} className="rounded-lg border border-red-900/60 px-3 py-1.5 text-[11px] text-red-300">Remove track</button></div>
      <label className="block text-xs text-neutral-300">Upload Audio File * (MP3, stereo, minimum 60 seconds)<input required type="file" accept=".mp3,audio/mpeg" onChange={e=>void validateAndSetTrackFile(index,e.target.files?.[0]||null)} className="mt-1 block w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white file:mr-3 file:rounded-lg file:border-0 file:bg-neutral-800 file:px-3 file:py-2 file:text-white"/></label>
      <h4 className="text-xs font-bold text-orange-300">Submission details</h4><div className="grid gap-3 sm:grid-cols-2">
      <label className="text-xs text-neutral-300">Is it an instrumental song?<select value={meta.instrumental?'Yes':'No'} onChange={e=>updateTrackMetadata(index,'instrumental',e.target.value==='Yes')} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option>No</option><option>Yes</option></select></label>
      <label className="text-xs text-neutral-300">Is it a Cover Song?<select value={meta.coverSong?'Yes':'No'} onChange={e=>updateTrackMetadata(index,'coverSong',e.target.value==='Yes')} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option>No</option><option>Yes</option></select></label>
      <label className="text-xs text-neutral-300">Song Title *<input required value={meta.title} onChange={e=>updateTrackMetadata(index,'title',e.target.value)} placeholder="Enter song title" className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">Primary Artist(s) *<input value={meta.primaryArtists} onChange={e=>updateTrackMetadata(index,'primaryArtists',e.target.value)} list="stbacademy-audio-known-artists" placeholder="Search Artists..." className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">Featuring Artist(s)<input value={meta.featuredArtists} onChange={e=>updateTrackMetadata(index,'featuredArtists',e.target.value)} list="stbacademy-audio-known-artists" placeholder="Search Artists..." className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">Genre *<select required value={meta.genre} onChange={e=>updateTrackMetadata(index,'genre',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option value="">Select genre...</option>{GENRES.map(x=><option key={x}>{x}</option>)}</select></label>
      <label className="text-xs text-neutral-300">Sub-genre<select value={meta.subGenre} onChange={e=>updateTrackMetadata(index,'subGenre',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option value="">Please select a genre first / optional</option>{SUB_GENRES.map(x=><option key={x}>{x}</option>)}</select></label>
      <label className="text-xs text-neutral-300">Label<input value={meta.label} onChange={e=>updateTrackMetadata(index,'label',e.target.value)} placeholder="Enter label name" className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">CLine (Optional)<input value={meta.cLine} onChange={e=>updateTrackMetadata(index,'cLine',e.target.value)} placeholder="CLine information" className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">PLine (Optional)<input value={meta.pLine} onChange={e=>updateTrackMetadata(index,'pLine',e.target.value)} placeholder="PLine information" className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">Version<input value={meta.version} onChange={e=>updateTrackMetadata(index,'version',e.target.value)} placeholder="Enter version" className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">Preview Start<input type="number" min="0" value={meta.previewStart} onChange={e=>updateTrackMetadata(index,'previewStart',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">Song Language *<select required value={meta.language} onChange={e=>updateTrackMetadata(index,'language',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option value="">Select language...</option>{OFFICIAL_LANGUAGES.map(x=><option key={x}>{x}</option>)}</select></label>
      <label className="text-xs text-neutral-300">Lyrics Language<select value={meta.lyricsLanguage} onChange={e=>updateTrackMetadata(index,'lyricsLanguage',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option value="">Select language...</option>{OFFICIAL_LANGUAGES.map(x=><option key={x}>{x}</option>)}</select></label>
      <label className="text-xs text-neutral-300">Country of Recording *<select required value={meta.countryOfRecording} onChange={e=>updateTrackMetadata(index,'countryOfRecording',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option value="">Select country...</option>{COUNTRIES.map(x=><option key={x}>{x}</option>)}</select></label>
      <label className="text-xs text-neutral-300">Parental Advisory<select value={meta.parentalAdvisory} onChange={e=>updateTrackMetadata(index,'parentalAdvisory',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option>No</option><option>Yes</option></select></label>
      <label className="text-xs text-neutral-300">Digital Release Date *<input required type="date" min={minReleaseDate()} value={meta.digitalReleaseDate} onChange={e=>updateTrackMetadata(index,'digitalReleaseDate',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300">Original Release Date<input type="date" value={meta.originalReleaseDate} onChange={e=>updateTrackMetadata(index,'originalReleaseDate',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      <label className="text-xs text-neutral-300 sm:col-span-2">Additional Information (Optional)<textarea maxLength={250} rows={2} value={meta.additionalInfo} onChange={e=>updateTrackMetadata(index,'additionalInfo',e.target.value)} placeholder="Text" className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/><span className="text-[10px] text-neutral-500">{meta.additionalInfo.length}/250</span></label>
      </div><div className="grid gap-3 sm:grid-cols-2">{([['clean','Clean'],['requestContentId','Request Content ID'],['publishing','Publishing'],['previouslyReleased','Is this song previously released?']] as const).map(([key,label])=><label key={key} className="text-xs text-neutral-300">{label}<select value={meta[key]?'Yes':'No'} onChange={e=>updateTrackMetadata(index,key,e.target.value==='Yes')} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"><option>No</option><option>Yes</option></select></label>)}</div>
      {meta.previouslyReleased&&<div className="grid gap-3 sm:grid-cols-3"><label className="text-xs text-neutral-300">Original release date *<input type="date" required value={meta.originalReleaseDate} onChange={e=>updateTrackMetadata(index,'originalReleaseDate',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label><label className="text-xs text-neutral-300">Original ISRC *<input required value={meta.previousISRC} onChange={e=>updateTrackMetadata(index,'previousISRC',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label><label className="text-xs text-neutral-300">Original UPC *<input required value={meta.previousUPC} onChange={e=>updateTrackMetadata(index,'previousUPC',e.target.value)} className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label></div>}
      <label className="block text-xs text-neutral-300">Lyrics (Optional)<textarea rows={3} value={meta.lyrics} onChange={e=>updateTrackMetadata(index,'lyrics',e.target.value)} placeholder="Enter lyrics" className="mt-1 w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-sm text-white"/></label>
      {([['writers','Writer(s)', 'Writer'],['publisherRows','Publisher(s)','Publisher'],['producerRows','Producer(s)','Producer'],['additionalPerformers','Additional Performer(s)','Performer'],['additionalContributors','Additional Contributor(s)','Contributor']] as const).map(([key,label,roleLabel])=><div key={key} className="space-y-2 rounded-lg border border-neutral-800 p-3"><div className="flex items-center justify-between"><h5 className="text-xs font-bold text-white">{label}</h5><button type="button" onClick={()=>updateTrackMetadata(index,key,[...meta[key],{name:'',role:''}])} className="text-[11px] text-orange-300">+ Add new {roleLabel}</button></div>{meta[key].map((row,rowIndex)=><div key={rowIndex} className="grid gap-2 sm:grid-cols-[1fr_1fr_auto]"><input value={row.name} onChange={e=>updateTrackMetadata(index,key,meta[key].map((r,i)=>i===rowIndex?{...r,name:e.target.value}:r))} placeholder="Name" className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"/><select value={row.role} onChange={e=>updateTrackMetadata(index,key,meta[key].map((r,i)=>i===rowIndex?{...r,role:e.target.value}:r))} className="rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 text-xs text-white"><option value="">Select role...</option>{(key==='writers'?['Composer (C)','Author (A)','Lyricist','Arranger']:key==='publisherRows'?['Publisher','Administrator','Sub-publisher']:key==='producerRows'?['Producer','Co-producer','Executive Producer']:key==='additionalPerformers'?['Vocals','Guitar','Piano','Drums','Other']:['Mixer','Mastering Engineer','Recording Engineer','Other']).map(role=><option key={role}>{role}</option>)}</select>{meta[key].length>1&&<button type="button" onClick={()=>updateTrackMetadata(index,key,meta[key].filter((_,i)=>i!==rowIndex))} className="px-2 text-red-300">×</button>}</div>)}</div>)}
      <p className="text-[10px] text-neutral-500">Writer credits should include at least one Composer (C) and one Author (A). Add at least one Producer.</p>
      </article>)}
      {trackMetadata.length===0&&<p className="rounded-xl border border-dashed border-neutral-700 p-6 text-center text-xs text-neutral-400">No songs added yet. Select “Add Song” to begin.</p>}</div>}
      {releaseType==='Single'&&files.length>1&&<label className="text-xs text-neutral-300 sm:col-span-2">Track titles (one per line, same order as files)<textarea value={trackTitles} onChange={e=>setTrackTitles(e.target.value)} rows={3} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white" placeholder={files.map(f=>f.name.replace(/\.mp3$/i,'')).join('\n')}/></label>}
      {releaseType==='Single'&&<label className="flex items-center gap-2 text-xs text-neutral-300"><input type="checkbox" checked={explicit} onChange={e=>setExplicit(e.target.checked)}/> Explicit content</label>}
      {releaseType==='Single'&&<label className="flex items-center gap-2 text-xs text-neutral-300"><input type="checkbox" checked={previouslyReleased} onChange={e=>setPreviouslyReleased(e.target.checked)}/> Previously released</label>}
      {releaseType==='Single'&&previouslyReleased&&<div className="sm:col-span-2 grid gap-3 sm:grid-cols-3"><label className="text-xs text-neutral-300">Original release date *<input required type="date" value={originalReleaseDate} onChange={e=>setOriginalReleaseDate(e.target.value)} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/></label><label className="text-xs text-neutral-300">Original ISRC *<input required value={previousIsrc} onChange={e=>setPreviousIsrc(e.target.value)} placeholder="e.g. ZA-ABC-26-00001" className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/></label><label className="text-xs text-neutral-300">Original UPC *<input required value={previousUpc} onChange={e=>setPreviousUpc(e.target.value)} placeholder="UPC / EAN" className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white"/></label></div>}
      {releaseType==='Single'&&<label className="text-xs text-neutral-300 sm:col-span-2">Lyrics (optional)<textarea value={lyrics} onChange={e=>setLyrics(e.target.value)} rows={4} className="mt-1 w-full rounded-xl border border-neutral-700 bg-neutral-950 px-3 py-2.5 text-sm text-white" placeholder="Enter complete lyrics for lyric platforms"/></label>}
      <div className="sm:col-span-2"><div className="mb-2 flex items-center justify-between"><p className="text-xs font-semibold text-neutral-300">Select digital stores <span className="ml-1 text-[10px] font-normal text-neutral-500">+90 more</span></p><button type="button" onClick={()=>setDspSelections(v=>v.length===STORES.length?[]:[...STORES])} className="text-[11px] text-orange-300">{dspSelections.length===STORES.length?"Clear all":"Select all DSPs"}</button></div><div className="flex flex-wrap gap-2">{STORES.map(name=><label key={name} className="flex items-center gap-2 rounded-lg border border-neutral-800 bg-neutral-950 px-3 py-2 text-xs text-neutral-300"><input type="checkbox" checked={dspSelections.includes(name)} onChange={()=>toggleStore(name)}/>{name}</label>)}</div></div>
      {error&&<p className="sm:col-span-2 text-xs text-red-400">{error}</p>}{notice&&<div className="sm:col-span-2 rounded-xl border border-orange-800 bg-orange-950/30 p-3 text-xs text-orange-300">{notice}</div>}
      <div className="sm:col-span-2"><button disabled={busy||(releaseType==='Single'?files.length===0:trackMetadata.length===0)||!artwork} type="submit" className="rounded-xl bg-orange-600 px-5 py-3 text-xs font-bold text-white disabled:opacity-50">{busy?'Uploading and submitting…':'Submit Audio Release'}</button></div>
    </form>
  </div></section>;
};
